  enabled: true
  name: cloudflare-ingress
  className: cloudflare-ingress
  controllerName: gateway.envoyproxy.io/gatewayclass-controller
  listener:
    port: 80
  envoyProxy:
    name: cloudflare-ingress-proxy
    resources:
      requests:
        cpu: 50m
        memory: 64Mi
      limits:
        cpu: 500m
        memory: 256Mi
  service:
    name: cloudflare-ingress
    port: 80

# --- Cloudflare Tunnel ---
tunnel:
  replicaCount: 2
  fullnameOverride: "cloudflared"

  image:
    repository: cloudflare/cloudflared
    tag: "2025.4.0"
    pullPolicy: IfNotPresent

  # Tunnel identity (set from secret when using OnePassword)
  id: ""
  name: ""
  protocol: ""
  noAutoupdate: true

  secret:
    type: onepassword
    onepassword:
      itemPath: ""
    manual:
      credentialsJson: ""

  ingress:
    routes: []
    catchAll:
      service: http_status:404

  service:
    type: ClusterIP
    port: 2000

  resources: {}
  priorityClassName: ""
  topologySpreadConstraints: []
  nodeSelector: {}
  tolerations: []
  affinity: {}
  podSecurityContext: {}

  securityContext:
    readOnlyRootFilesystem: true
