      },
      body: JSON.stringify({
        description,
        public: false,
        files: { "output.md": { content } },
      }),
    });
    if (!res.ok) throw new Error(`GitHub API error: ${res.status}`);
    const data = (await res.json()) as { html_url: string };
    return data.html_url;
  }
}
